import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:go_router/go_router.dart';import '../../../shared/providers/providers.dart';
class LoginScreen extends ConsumerStatefulWidget{const LoginScreen({super.key});@override ConsumerState<LoginScreen> createState()=>_State();}class _State extends ConsumerState<LoginScreen>{final email=TextEditingController(),password=TextEditingController();bool loading=false;String? error;Future<void> submit()async{setState((){loading=true;error=null;});try{final r=await ref.read(apiProvider).dio.post('/auth/login',data:{'email':email.text.trim(),'password':password.text});await ref.read(tokenStoreProvider).save(r.data['data']['session']);if(mounted)context.go('/');}catch(e){setState(()=>error='Sign in failed. Check your details and connection.');}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(),body:SafeArea(child:ListView(padding:const EdgeInsets.all(24),children:[Text('Welcome back',style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.bold)),const SizedBox(height:8),const Text('Sign in to save listings and manage your provider profile.'),const SizedBox(height:28),TextField(controller:email,keyboardType:TextInputType.emailAddress,decoration:const InputDecoration(labelText:'Email')),const SizedBox(height:12),TextField(controller:password,obscureText:true,decoration:const InputDecoration(labelText:'Password')),if(error!=null)Padding(padding:const EdgeInsets.only(top:12),child:Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error))),const SizedBox(height:20),FilledButton(onPressed:loading?null:submit,child:Padding(padding:const EdgeInsets.all(14),child:Text(loading?'Signing in…':'Sign in'))),TextButton(onPressed:()=>showDialog(context:context,builder:(_)=>const AlertDialog(title:Text('Registration'),content:Text('Use POST /auth/register or add your organisation registration flow here.'))),child:const Text('Create an account'))])));}
